                              .DataWidth(16)
                              )
                            u_RAM_N_bank1 (.clk(clk),
                                           .enb(enb),
                                           .wr_din_re(dataIn_re),
                                           .wr_din_im(dataIn_im),
                                           .wr_addr(sliceWNyqA_out1[1]),
                                           .wr_en(AND_weN_out1[1]),
                                           .rd_addr(sliceRNyqA_out1[1]),
                                           .dout_re(pri_rd_out_1_re_4),
                                           .dout_im(pri_rd_out_1_im_4)
                                           );

  SimpleDualPortRAM_generic #(.AddrWidth(7),
                              .DataWidth(16)
                              )
                            u_RAM_N_bank2 (.clk(clk),
                                           .enb(enb),
                                           .wr_din_re(dataIn_re),
                                           .wr_din_im(dataIn_im),
                                           .wr_addr(sliceWNyqA_out1[2]),
                                           .wr_en(AND_weN_out1[2]),
                                           .rd_addr(sliceRNyqA_out1[2]),
                                           .dout_re(pri_rd_out_1_re_5),
                                           .dout_im(pri_rd_out_1_im_5)
                                           );

  assign RAM_N_out1_re[0] = pri_rd_out_1_re_3;
  assign RAM_N_out1_re[1] = pri_rd_out_1_re_4;
  assign RAM_N_out1_re[2] = pri_rd_out_1_re_5;

  assign RAM_N_out1_im[0] = pri_rd_out_1_im_3;
  assign RAM_N_out1_im[1] = pri_rd_out_1_im_4;
  assign RAM_N_out1_im[2] = pri_rd_out_1_im_5;

  always @* begin
    if (UD_nyq_out1 == 1'b0) begin
      for(SW_nyq_t_1 = 32'sd0; SW_nyq_t_1 <= 32'sd2; SW_nyq_t_1 = SW_nyq_t_1 + 32'sd1) begin
        SW_nyq_out1_re[SW_nyq_t_1] = RAM_M_out1_re[SW_nyq_t_1];
        SW_nyq_out1_im[SW_nyq_t_1] = RAM_M_out1_im[SW_nyq_t_1];
      end
    end
    else begin
      for(SW_nyq_t_0_0 = 32'sd0; SW_nyq_t_0_0 <= 32'sd2; SW_nyq_t_0_0 = SW_nyq_t_0_0 + 32'sd1) begin
        SW_nyq_out1_re[SW_nyq_t_0_0] = RAM_N_out1_re[SW_nyq_t_0_0];
        SW_nyq_out1_im[SW_nyq_t_0_0] = RAM_N_out1_im[SW_nyq_t_0_0];
      end
    end
  end

  assign CRI_x_out1[0] = SW_nyq_out1_re[0];
  assign CRI_x_out1[1] = SW_nyq_out1_re[1];
  assign CRI_x_out1[2] = SW_nyq_out1_re[2];

  assign kernIn_re[0] = kernIn_re_0;
  assign kernIn_re[1] = kernIn_re_1;
  assign kernIn_re[2] = kernIn_re_2;

  assign kernIn_im[0] = kernIn_im_0;
  assign kernIn_im[1] = kernIn_im_1;
  assign kernIn_im[2] = kernIn_im_2;

  always @(posedge clk or posedge reset)
    begin : UD_h_process
      if (reset == 1'b1) begin
        for(UD_h_t_1 = 32'sd0; UD_h_t_1 <= 32'sd2; UD_h_t_1 = UD_h_t_1 + 32'sd1) begin
          UD_h_out1_re[UD_h_t_1] <= 16'sb0000000000000000;
          UD_h_out1_im[UD_h_t_1] <= 16'sb0000000000000000;
        end
      end
      else begin
        if (enb) begin
          for(UD_h_t_0 = 32'sd0; UD_h_t_0 <= 32'sd2; UD_h_t_0 = UD_h_t_0 + 32'sd1) begin
            UD_h_out1_re[UD_h_t_0] <= kernIn_re[UD_h_t_0];
            UD_h_out1_im[UD_h_t_0] <= kernIn_im[UD_h_t_0];
          end
        end
      end
    end

  assign CRI_h_out1[0] = UD_h_out1_re[0];
  assign CRI_h_out1[1] = UD_h_out1_re[1];
  assign CRI_h_out1[2] = UD_h_out1_re[2];


  genvar t_0_011;
  generate
    for(t_0_011 = 32'sd0; t_0_011 <= 32'sd2; t_0_011 = t_0_011 + 32'sd1) begin:Prod_rr_out1_gen
      assign Prod_rr_out1[t_0_011] = CRI_x_out1[t_0_011] * CRI_h_out1[t_0_011];
    end
  endgenerate

  assign CRI_x_out2[0] = SW_nyq_out1_im[0];
  assign CRI_x_out2[1] = SW_nyq_out1_im[1];
  assign CRI_x_out2[2] = SW_nyq_out1_im[2];

  assign CRI_h_out2[0] = UD_h_out1_im[0];
  assign CRI_h_out2[1] = UD_h_out1_im[1];
  assign CRI_h_out2[2] = UD_h_out1_im[2];


  genvar t_0_021;
  generate
    for(t_0_021 = 32'sd0; t_0_021 <= 32'sd2; t_0_021 = t_0_021 + 32'sd1) begin:Prod_ii_out1_gen
      assign Prod_ii_out1[t_0_021] = CRI_x_out2[t_0_021] * CRI_h_out2[t_0_021];
    end
  endgenerate


  genvar t_0_031;
  generate
    for(t_0_031 = 32'sd0; t_0_031 <= 32'sd2; t_0_031 = t_0_031 + 32'sd1) begin:Add_re_out1_gen
      assign Add_re_sub_cast[t_0_031] = {Prod_rr_out1[t_0_031][31], Prod_rr_out1[t_0_031]};
      assign Add_re_sub_cast_1[t_0_031] = {Prod_ii_out1[t_0_031][31], Prod_ii_out1[t_0_031]};
      assign Add_re_out1[t_0_031] = Add_re_sub_cast[t_0_031] - Add_re_sub_cast_1[t_0_031];
    end
  endgenerate


  genvar t_0_041;
  generate
    for(t_0_041 = 32'sd0; t_0_041 <= 32'sd2; t_0_041 = t_0_041 + 32'sd1) begin:Prod_ri_out1_gen
      assign Prod_ri_out1[t_0_041] = CRI_x_out1[t_0_041] * CRI_h_out2[t_0_041];
    end
  endgenerate


  genvar t_0_051;
  generate
    for(t_0_051 = 32'sd0; t_0_051 <= 32'sd2; t_0_051 = t_0_051 + 32'sd1) begin:Prod_ir_out1_gen
      assign Prod_ir_out1[t_0_051] = CRI_x_out2[t_0_051] * CRI_h_out1[t_0_051];
    end
  endgenerate


  genvar t_0_061;
  generate
    for(t_0_061 = 32'sd0; t_0_061 <= 32'sd2; t_0_061 = t_0_061 + 32'sd1) begin:Add_im_out1_gen
      assign Add_im_add_cast[t_0_061] = {Prod_ri_out1[t_0_061][31], Prod_ri_out1[t_0_061]};
      assign Add_im_add_cast_1[t_0_061] = {Prod_ir_out1[t_0_061][31], Prod_ir_out1[t_0_061]};
      assign Add_im_out1[t_0_061] = Add_im_add_cast[t_0_061] + Add_im_add_cast_1[t_0_061];
    end
  endgenerate

  assign RIC_out1_re[0] = Add_re_out1[0];
  assign RIC_out1_re[1] = Add_re_out1[1];
  assign RIC_out1_re[2] = Add_re_out1[2];

  assign RIC_out1_im[0] = Add_im_out1[0];
  assign RIC_out1_im[1] = Add_im_out1[1];
  assign RIC_out1_im[2] = Add_im_out1[2];

  always @(posedge clk or posedge reset)
    begin : UD_y_process
      if (reset == 1'b1) begin
        for(UD_y_t_1 = 32'sd0; UD_y_t_1 <= 32'sd2; UD_y_t_1 = UD_y_t_1 + 32'sd1) begin
          UD_y_reg_re[UD_y_t_1] <= 33'sh000000000;
          UD_y_reg_im[UD_y_t_1] <= 33'sh000000000;
        end
      end
      else begin
        if (enb) begin
          for(UD_y_t_0_0 = 32'sd0; UD_y_t_0_0 <= 32'sd2; UD_y_t_0_0 = UD_y_t_0_0 + 32'sd1) begin
            UD_y_reg_re[UD_y_t_0_0] <= UD_y_reg_next_re[UD_y_t_0_0];
            UD_y_reg_im[UD_y_t_0_0] <= UD_y_reg_next_im[UD_y_t_0_0];
          end
        end
      end
    end
  genvar t_021;
  generate
    for(t_021 = 32'sd0; t_021 <= 32'sd2; t_021 = t_021 + 32'sd1) begin:UD_y_reg_next_im_gen
      assign UD_y_out1_re[t_021] = UD_y_reg_re[t_021];
      assign UD_y_out1_im[t_021] = UD_y_reg_im[t_021];
      assign UD_y_reg_next_re[t_021] = RIC_out1_re[t_021];
      assign UD_y_reg_next_im[t_021] = RIC_out1_im[t_021];
    end
  endgenerate

  assign in0_0_re = UD_y_out1_re[0];

  assign in0_0_im = UD_y_out1_im[0];

  assign in0_1_re = UD_y_out1_re[1];

  assign in0_1_im = UD_y_out1_im[1];

  // ---- Tree sum implementation ----
  assign sumC_stage1_add_cast = {in0_0_re[32], in0_0_re};
  assign sumC_stage1_add_cast_1 = {in0_1_re[32], in0_1_re};
  assign sumC_stage1_1_re = sumC_stage1_add_cast + sumC_stage1_add_cast_1;
  assign sumC_stage1_add_cast_2 = {in0_0_im[32], in0_0_im};
  assign sumC_stage1_add_cast_3 = {in0_1_im[32], in0_1_im};
  assign sumC_stage1_1_im = sumC_stage1_add_cast_2 + sumC_stage1_add_cast_3;

  assign in0_2_re = UD_y_out1_re[2];

  assign in0_2_im = UD_y_out1_im[2];

  assign sumC_stage1_2_re = {in0_2_re[32], in0_2_re};
  assign sumC_stage1_2_im = {in0_2_im[32], in0_2_im};

  assign sumC_stage2_add_cast = {sumC_stage1_1_re[33], sumC_stage1_1_re};
  assign sumC_stage2_add_cast_1 = {sumC_stage1_2_re[33], sumC_stage1_2_re};
  assign sumC_stage2_re = sumC_stage2_add_cast + sumC_stage2_add_cast_1;
  assign sumC_stage2_add_cast_2 = {sumC_stage1_1_im[33], sumC_stage1_1_im};
  assign sumC_stage2_add_cast_3 = {sumC_stage1_2_im[33], sumC_stage1_2_im};
  assign sumC_stage2_im = sumC_stage2_add_cast_2 + sumC_stage2_add_cast_3;

  always @(posedge clk or posedge reset)
    begin : UD_sum_process
      if (reset == 1'b1) begin
        UD_sum_out1_re <= 35'sh000000000;
        UD_sum_out1_im <= 35'sh000000000;
      end
      else begin
        if (enb) begin
          UD_sum_out1_re <= sumC_stage2_re;
          UD_sum_out1_im <= sumC_stage2_im;
        end
      end
    end

  assign dataOut_re = UD_sum_out1_re;

  assign dataOut_im = UD_sum_out1_im;

  always @(posedge clk or posedge reset)
    begin : vDly_process
      if (reset == 1'b1) begin
        vDly_reg <= {3{1'b0}};
      end
      else begin
        if (enb) begin
          vDly_reg[0] <= UD_rd_out1;
          vDly_reg[32'sd2:32'sd1] <= vDly_reg[32'sd1:32'sd0];
        end
      end
    end

  assign vDly_out1 = vDly_reg[2];

  assign validOut = vDly_out1;

  always @(posedge clk or posedge reset)
    begin : dDly_process
      if (reset == 1'b1) begin
        dDly_reg <= {3{1'b0}};
      end
      else begin
        if (enb) begin
          dDly_reg[0] <= AND_rLast_out1;
          dDly_reg[32'sd2:32'sd1] <= dDly_reg[32'sd1:32'sd0];
        end
      end
    end

  assign dDly_out1 = dDly_reg[2];

  assign doneOut = dDly_out1;

  always @(posedge clk or posedge reset)
    begin : mDly_process
      if (reset == 1'b1) begin
        for(mDly_t_1 = 32'sd0; mDly_t_1 <= 32'sd2; mDly_t_1 = mDly_t_1 + 32'sd1) begin
          mDly_reg[mDly_t_1] <= 7'b0000000;
        end
      end
      else begin
        if (enb) begin
          for(mDly_t_0_1 = 32'sd0; mDly_t_0_1 <= 32'sd2; mDly_t_0_1 = mDly_t_0_1 + 32'sd1) begin
            mDly_reg[mDly_t_0_1] <= mDly_reg_next[mDly_t_0_1];
          end
        end
      end
    end

  always @* begin
    mDly_out1 = mDly_reg[2];
    mDly_reg_next[0] = mCnt_out1;

    for(mDly_t_0_0 = 32'sd0; mDly_t_0_0 <= 32'sd1; mDly_t_0_0 = mDly_t_0_0 + 32'sd1) begin
      mDly_reg_next[mDly_t_0_0 + 32'sd1] = mDly_reg[mDly_t_0_0];
    end

  end

  assign mIdxOut = mDly_out1;

  assign kernRd = UD_rd_out1;

  assign tileDone = AND_tile_out1;

endmodule  // cmac2d_block

